import React, { useState, useEffect } from "react";
import "./Dashboard.css";

function Dashboard() {
  const [file, setFile] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [type, setType] = useState("");
  const [darkMode, setDarkMode] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");
  const [loading, setLoading] = useState(false);

  const [showProfile, setShowProfile] = useState(false);
  const [showTheme, setShowTheme] = useState(false);

  const [profile, setProfile] = useState({
    name: "User",
    email: "user@email.com"
  });

  useEffect(() => {
    const savedProfile = JSON.parse(localStorage.getItem("profile"));
    if (savedProfile) setProfile(savedProfile);
  }, []);

  const detectSource = (transactions) => {
    if (!transactions || transactions.length === 0) return "Not uploaded";

    const text = transactions
      .map((t) => t.description?.toLowerCase() || "")
      .join(" ");

    if (text.includes("gpay") || text.includes("upi"))
      return "GPay Statement";
    if (text.includes("hdfc")) return "HDFC Bank";
    if (text.includes("sbi")) return "SBI Bank";

    return "Bank Statement";
  };

  const handleUpload = async () => {
    if (!file) return alert("Please select a PDF file");

    setLoading(true);

    const formData = new FormData();
    formData.append("file", file);

    const res = await fetch("http://localhost:8000/upload-statement/", {
      method: "POST",
      body: formData,
    });

    const data = await res.json();

    setTransactions(data.transactions || []);
    setType(detectSource(data.transactions));

    const history = JSON.parse(localStorage.getItem("history")) || [];

    history.unshift({
      date: new Date().toLocaleString(),
      type: detectSource(data.transactions),
      count: data.transactions?.length || 0,
      transactions: data.transactions || []
    });

    localStorage.setItem("history", JSON.stringify(history));

    setLoading(false);
  };

  const deleteHistory = (index) => {
    const history = JSON.parse(localStorage.getItem("history")) || [];
    history.splice(index, 1);
    localStorage.setItem("history", JSON.stringify(history));
    setActiveTab("history");
  };

  return (
    <div className={`dashboard-main ${darkMode ? "dark" : ""}`}>
      <div className="container">

        {/* NAVBAR */}
        <div className="navbar">
          <div>
            <div className="logo">FinSight</div>
            <div style={{ fontSize: "13px", color: "#6b7280" }}>
              Personal Expense Intelligence
            </div>
          </div>

          <div className="nav-actions" style={{ display: "flex", alignItems: "center", gap: "15px" }}>

            {/* TABS */}
            <div className="tabs">
              <span
                className={`tab ${activeTab === "overview" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("overview")}
              >
                Overview
              </span>

              <span
                className={`tab ${activeTab === "history" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("history")}
              >
                History
              </span>
            </div>

            {/* PROFILE ICON */}
            <div
              onClick={() => {
                setShowProfile(!showProfile);
                setShowTheme(false);
              }}
              style={{
                width: "40px",
                height: "40px",
                borderRadius: "50%",
                background: "linear-gradient(135deg, #4f6df5, #6a85ff)",
                color: "white",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontWeight: "600",
                cursor: "pointer"
              }}
            >
              {profile.name.charAt(0).toUpperCase()}
            </div>

            {/* THEME ICON */}
            <div
              onClick={() => {
                setShowTheme(!showTheme);
                setShowProfile(false);
              }}
              style={{
                width: "34px",
                height: "34px",
                borderRadius: "50%",
                background: darkMode ? "#111" : "#e5e7eb",
                cursor: "pointer",
                border: "1px solid #ccc"
              }}
            ></div>
          </div>
        </div>

        {/* THEME DROPDOWN (LIKE IMAGE) */}
        {showTheme && (
          <div style={{
            position: "absolute",
            top: "70px",
            right: "40px",
            background: "#111",
            borderRadius: "14px",
            padding: "15px",
            width: "180px",
            color: "white",
            boxShadow: "0 10px 30px rgba(0,0,0,0.3)",
            zIndex: 1000
          }}>

            {/* Avatar */}
            <div style={{
              display: "flex",
              justifyContent: "center",
              marginBottom: "15px"
            }}>
              <div style={{
                width: "50px",
                height: "50px",
                borderRadius: "50%",
                background: "conic-gradient(#f97316, #22c55e, #3b82f6, #f97316)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontWeight: "bold",
                fontSize: "18px"
              }}>
                {profile.name.charAt(0).toUpperCase()}
              </div>
            </div>

            {/* LIGHT */}
            <div
              onClick={() => setDarkMode(false)}
              style={{
                display: "flex",
                alignItems: "center",
                gap: "10px",
                padding: "10px",
                borderRadius: "10px",
                cursor: "pointer"
              }}
            >
              ☀️ <span>Light</span>
            </div>

            {/* DARK */}
            <div
              onClick={() => setDarkMode(true)}
              style={{
                display: "flex",
                alignItems: "center",
                gap: "10px",
                padding: "10px",
                borderRadius: "10px",
                cursor: "pointer"
              }}
            >
              🌙 <span>Dark</span>
            </div>
          </div>
        )}

        {/* PROFILE DROPDOWN */}
        {showProfile && (
          <div style={{
            position: "absolute",
            top: "70px",
            right: "250px",
            width: "260px",
            background: "white",
            borderRadius: "16px",
            padding: "20px",
            boxShadow: "0 10px 30px rgba(0,0,0,0.1)",
            zIndex: 1000
          }}>
            <h3>Profile</h3>

            <input
              value={profile.name}
              onChange={(e) =>
                setProfile({ ...profile, name: e.target.value })
              }
            />

            <input
              value={profile.email}
              onChange={(e) =>
                setProfile({ ...profile, email: e.target.value })
              }
              style={{ marginTop: "10px" }}
            />

            <button
              style={{ marginTop: "15px" }}
              onClick={() => {
                localStorage.setItem("profile", JSON.stringify(profile));
                setShowProfile(false);
              }}
            >
              Save
            </button>
          </div>
        )}

        {/* HERO */}
        <div className="hero">
          <h1>
            Welcome, <span style={{ color: "#4f6df5" }}>{profile.name}</span>
          </h1>
        </div>

        {/* OVERVIEW */}
        {activeTab === "overview" && (
          <>
            <div className="kpi-grid">
              <div className="kpi-card">
                <h4>Statement Source</h4>
                <p>{type || "Not uploaded"}</p>
              </div>

              <div className="kpi-card">
                <h4>Total Transactions</h4>
                <p>{transactions.length}</p>
              </div>

              <div className="kpi-card">
                <h4>Status</h4>
                <p>{transactions.length ? "Processed" : "Waiting"}</p>
              </div>
            </div>

            <div className="top-section">
              <div className="card upload-card">
                <h3>Upload Statement</h3>

                <div className="upload-row">
                  <input
                    type="file"
                    accept=".pdf"
                    onChange={(e) => setFile(e.target.files[0])}
                  />

                  <button onClick={handleUpload}>
                    {loading ? "Processing..." : "Analyze Statement"}
                  </button>
                </div>
              </div>

              <div className="card summary-card">
                <h3>Insights Summary</h3>
                <p>AI-powered transaction analysis with categorization</p>
              </div>
            </div>
          </>
        )}

        {/* HISTORY */}
        {activeTab === "history" && (
          <div className="card table-card">
            <h3>History</h3>

            <div className="table-wrapper">
              <table>
                <thead>
                  <tr>
                    <th>Date</th>
                    <th>Source</th>
                    <th>Transactions</th>
                    <th style={{ textAlign: "right" }}>Actions</th>
                  </tr>
                </thead>

                <tbody>
                  {(JSON.parse(localStorage.getItem("history")) || []).map((h, i) => (
                    <tr key={i}>
                      <td>{h.date}</td>
                      <td>{h.type}</td>
                      <td>{h.count}</td>
                      <td style={{ textAlign: "right" }}>
                        <button onClick={() => {
                          setTransactions(h.transactions || []);
                          setType(h.type);
                          setActiveTab("overview");
                        }}>
                          View
                        </button>

                        <button
                          style={{ marginLeft: "10px" }}
                          onClick={() => deleteHistory(i)}
                        >
                          Delete
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>

              </table>
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

export default Dashboard;
